'use client';
import { useEffect, useState, type ReactNode } from 'react';
import { cx } from '../lib/cx';
import { useControllable, useReducedMotion } from '../lib/hooks';
import { Icon } from '../lib/icons';
import { Avatar, Spin, Swap, useGrow, useMounted, useReflow } from '../lib/motion';
import { useColumns } from '../lib/columns';
import '../designme.css';
import './task-table.css';

export type TaskStatus = 'running' | 'failed' | 'queued' | 'paused' | 'done';

export interface Task {
  id: string;
  /** What the agent is doing, like "Audit pricing contrast" */
  name: string;
  status: TaskStatus;
  /** The agent on it, shown as a small avatar and a name */
  agent: { name: string; initials: string; color: string };
  /** In dollars, shown as $0.42 */
  cost: number;
  /** Minutes since it last changed, shown as "14m ago", or "Just now" at 0 */
  updated: number;
}

export type TaskSortKey = 'name' | 'status' | 'agent' | 'cost' | 'updated';
export interface TaskSort { key: TaskSortKey; desc?: boolean }
export type TaskAction = 'pause' | 'retry' | 'cancel';

export interface TaskTableProps {
  tasks: Task[];
  /** The name in the header. Defaults to "Agent tasks" */
  title?: string;
  /** The quiet line beside the name. Defaults to a count of tasks and how many are running (nothing while the table is
   *  empty, as the empty note says so) */
  summary?: string;
  /** Ids of the selected tasks. Leave it out to let the checkboxes and rows toggle it */
  selected?: string[];
  defaultSelected?: string[];
  onSelectedChange?: (ids: string[]) => void;
  /** The column the rows are sorted by. Leave it out to let the headers set it. Defaults to updated, newest first */
  sort?: TaskSort;
  defaultSort?: TaskSort;
  onSortChange?: (sort: TaskSort) => void;
  /** A button in the header while tasks are selected. The selection clears after it; cancelled rows slide away first */
  onAction?: (action: TaskAction, ids: string[]) => void;
  /** What shows when there are no tasks. Defaults to a short "No agent tasks" note under a small sketch of the table */
  empty?: ReactNode;
  /** A button under the empty note, like { label: 'Bring them back', onClick } */
  emptyAction?: { label: string; onClick: () => void };
  className?: string;
}

const STATUS: Record<TaskStatus, { label: string; rank: number; tone: string; glyph: () => ReactNode }> = {
  running: { label: 'Running', rank: 0, tone: 'run', glyph: () => <Spin /> },
  failed: { label: 'Failed', rank: 1, tone: 'fail', glyph: () => <Icon name="alert" size="xs" /> },
  queued: { label: 'Queued', rank: 2, tone: 'wait', glyph: () => <span className="dm-dot" /> },
  paused: { label: 'Paused', rank: 3, tone: 'pause', glyph: () => <Icon name="pause" size="xs" /> },
  done: { label: 'Done', rank: 4, tone: 'done', glyph: () => <Icon name="ok" size="xs" /> }
};
const COLUMNS: { key: TaskSortKey; label: string; right?: boolean; name?: boolean }[] = [
  { key: 'name', label: 'Task', name: true }, { key: 'status', label: 'Status' }, { key: 'agent', label: 'Agent' },
  { key: 'cost', label: 'Cost', right: true }, { key: 'updated', label: 'Updated', right: true }
];
const FIELD: Record<TaskSortKey, (t: Task) => string | number> = {
  name: t => t.name, status: t => STATUS[t.status].rank, agent: t => t.agent.name, cost: t => t.cost, updated: t => t.updated
};
const ACTIONS: { key: TaskAction; label: string; icon: 'pause' | 'refresh' | 'x' }[] = [
  { key: 'pause', label: 'Pause', icon: 'pause' }, { key: 'retry', label: 'Retry', icon: 'refresh' }, { key: 'cancel', label: 'Cancel', icon: 'x' }
];
const ago = (m: number) => (m ? m + 'm ago' : 'Just now');

/** A small sketch of the table's rows for the empty note: a soft card in Soft, Clean's white card in Clean; Blueprint keeps
 *  its mark */
const ART = <span className="dm-ttx-em-art" aria-hidden="true">{[0, 1, 2].map(i => <span key={i} className="dm-r"><i className="dm-t" /><i className="dm-l" /></span>)}</span>;

/** A tick that springs in, and the dash select-all shows while only some rows are picked */
const Tick = () => <><Icon name="check" size="xs" className="dm-ck-y" /><Icon name="minus" size="xs" className="dm-ck-m" /></>;

/**
 * Agent tasks in a sortable table. Pick rows and the header turns into what you can do to them; rows glide when the
 * order changes, cancelled ones slide away, and an empty table says so. The card grows and shrinks with its rows, keeping
 * no room for them.
 */
export function TaskTable({
  tasks, title = 'Agent tasks', summary, selected, defaultSelected = [], onSelectedChange, sort, defaultSort = { key: 'updated' }, onSortChange,
  onAction, empty, emptyAction, className
}: TaskTableProps) {
  const [sel, setSel] = useControllable(selected, defaultSelected, onSelectedChange);
  const [by, setBy] = useControllable(sort, defaultSort, onSortChange);
  const [leaving, setLeaving] = useState<string[]>([]);
  const reduce = useReducedMotion();
  const f = FIELD[by.key];
  const rows = [...tasks].sort((a, b) => { const x = f(a), y = f(b); return (x > y ? 1 : x < y ? -1 : 0) * (by.desc ? -1 : 1); });
  const picked = sel.filter(id => tasks.some(t => t.id === id) && !leaving.includes(id));
  const n = picked.length, all = n === 0 ? 'false' : n === tasks.length ? 'true' : 'mixed';
  // the header keeps its count while it slides back to the title
  const [shown, setShown] = useState(n);
  if (n && n !== shown) setShown(n);
  const running = tasks.filter(t => t.status === 'running').length;
  const line = summary ?? (tasks.length ? `${tasks.length} task${tasks.length === 1 ? '' : 's'}, ${running} running` : '');

  // rows glide to their new places, a short glide from where they are on screen, so sorting again mid-glide carries on from
  // there; rows that come back fade in. Cancelled rows slide away on their own (dm-ttx-out). The rows play their entrance
  // once, so a sort that moves them doesn't play it again
  // the card keeps no room for rows to come or for the empty note (owner, 18 Nov): it follows its rows' height, eased
  const [panel, inner] = useGrow();
  useReflow(panel, 'tbody > tr[data-id]', { by: 'data-id', leave: false });
  const mounted = useMounted();
  // the columns resize and move as in a spreadsheet; Task stays first with its checkbox, and on a narrow card, where each task
  // is a small card (528px of content or less), every row keeps its own order
  const [wide, setWide] = useState(true);
  useEffect(() => { const el = panel.current; if (!el) return; const ro = new ResizeObserver(() => setWide(el.clientWidth - 32 > 528)); ro.observe(el); return () => ro.disconnect(); }, [panel]);
  const cols = useColumns<TaskSortKey>(COLUMNS.map(c => c.key), { lead: 1, move: ['status', 'agent', 'cost', 'updated'], min: { name: 140, status: 104, agent: 96, cost: 72, updated: 88 }, wide, name: k => COLUMNS.find(c => c.key === k)!.label });
  const COL = Object.fromEntries(COLUMNS.map(c => [c.key, c])) as Record<TaskSortKey, (typeof COLUMNS)[number]>;
  const cell = (t: Task, k: TaskSortKey): ReactNode => {
    const st = STATUS[t.status];
    switch (k) {
      case 'name': return <td key={k} data-col={k} className="dm-nm">{t.name}</td>;
      case 'status': return <td key={k} data-col={k}><span className="dm-ttx-st" data-s={st.tone}><span key={t.status} className="dm-sv dm-ttx-sin">{st.glyph()}<span>{st.label}</span></span></span></td>;
      case 'agent': return <td key={k} data-col={k}><span className="dm-ag"><Avatar initials={t.agent.initials} color={t.agent.color} /><span>{t.agent.name}</span></span></td>;
      case 'cost': return <td key={k} data-col={k} className="dm-r dm-num">${t.cost.toFixed(2)}</td>;
      default: return <td key={k} data-col={k} className="dm-r dm-num dm-up"><Swap>{ago(t.updated)}</Swap></td>;
    }
  };

  const toggle = (id: string) => setSel(sel.includes(id) ? sel.filter(x => x !== id) : [...sel, id]);
  const sortBy = (key: TaskSortKey) => setBy(key === by.key ? { key, desc: !by.desc } : { key, desc: false });
  const act = (a: TaskAction) => {
    const ids = picked; setSel([]);
    if (a !== 'cancel' || reduce) { onAction?.(a, ids); return; }
    setLeaving(ids);
    setTimeout(() => { onAction?.(a, ids); setLeaving([]); }, 250);
  };

  return (
    <div data-dm="" className={cx('dm-ttx-box', className)} style={{ containerType: 'inline-size', width: '100%' }}>
      <div ref={panel} className={cx('dm-ttx dm-panel dm-growing', n > 0 && 'dm-selecting', !tasks.length && 'dm-none')}>
        <div ref={inner} className="dm-grow">
        {/* the head's mark is the column every row's checkbox is centred in; the title and each task's name start after it */}
        <div className="dm-ttx-hd">
          <span className="dm-ttx-hi" aria-hidden="true"><Icon name="list" /></span>
          <div className="dm-ttx-hx">
            <div className="dm-ttx-ti" inert={n > 0}><b>{title}</b><Swap className="dm-muted dm-num dm-ttx-sum">{line}</Swap></div>
            <div className="dm-ttx-sb" inert={n === 0}>
              <span className="dm-ttx-n dm-num">{shown} selected</span>
              {ACTIONS.map(a => (
                <button key={a.key} type="button" className={cx('dm-pill dm-ghost dm-sm', a.key === 'cancel' && 'dm-ttx-del')} onClick={() => act(a.key)}><Icon name={a.icon} size="xs" />{a.label}</button>
              ))}
              <span className="dm-ttx-sp" />
              <button type="button" className="dm-pill dm-ghost dm-sm dm-ttx-clr" onClick={() => setSel([])}>Clear</button>
            </div>
          </div>
        </div>
        <div className="dm-ttx-sc">
          <table {...cols.table} className={cx('dm-ttx-t', cols.sized && 'dm-cols-rz')}>
            {cols.colgroup}
            <thead>
              <tr>
                <th className="dm-ck">
                  <button type="button" className="dm-ttx-cb dm-ttx-all" role="checkbox" aria-checked={all} aria-label="Select all" onClick={() => setSel(all === 'true' ? [] : tasks.map(t => t.id))}><Tick /></button>
                </th>
                {cols.order.map(k => { const c = COL[k]; return (
                  <th key={c.key} {...cols.head(c.key)} className={c.right ? 'dm-r' : c.name ? 'dm-nm' : undefined} aria-sort={by.key === c.key ? (by.desc ? 'descending' : 'ascending') : 'none'}>
                    <button type="button" className={cx('dm-ttx-s', by.key === c.key && 'dm-on', by.desc && 'dm-desc')} onClick={() => sortBy(c.key)}>
                      {c.label}<span className="dm-ar"><Icon name="chev-u" size="xs" /></span>
                    </button>
                    {cols.handle(c.key)}
                  </th>
                ); })}
              </tr>
            </thead>
            <tbody>
              {rows.map((t, i) => {
                const on = picked.includes(t.id);
                return (
                  <tr key={t.id} data-id={t.id} className={cx(!mounted && 'dm-enter', on && 'dm-sel', leaving.includes(t.id) && 'dm-ttx-out')} style={mounted ? undefined : { animationDelay: i * 30 + 'ms' }} onClick={() => toggle(t.id)}>
                    <td className="dm-ck">
                      <button type="button" className="dm-ttx-cb" role="checkbox" aria-checked={on} aria-label={'Select ' + t.name}><Tick /></button>
                    </td>
                    {cols.order.map(k => cell(t, k))}
                  </tr>
                );
              })}
              {!tasks.length && (
                <tr className="dm-ttx-empty dm-enter">
                  <td colSpan={6}>
                    {empty ?? (
                      <div className="dm-ttx-em">
                        <span className="dm-ic"><Icon name="check" /></span>
                        {ART}
                        <b>No agent tasks</b>
                        <span>Everything has finished or been cancelled.</span>
                        {emptyAction && <button type="button" className="dm-pill dm-ghost dm-sm" onClick={emptyAction.onClick}><Icon name="refresh" size="xs" />{emptyAction.label}</button>}
                      </div>
                    )}
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
        </div>
      </div>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Task table ---------- */
/* agent tasks in a sortable table, with bulk actions in the head while rows are picked. The card sits on two columns
   (owner, 18 Nov), its content 16px from every edge: the head's neutral mark in a 28px column with every row's checkbox
   centred under it, and the title, the Task heading and each task's name 12px after it. A row's hover and picked fill is a
   quiet grey that spans the content box, no wider, with round corners (no lines between rows cut through it); the costs,
   the times and their headings sit 8px inside it, and Clear's words end over them. No room is kept: the card grows and
   shrinks with its rows (grow()) and stays centred, and an empty table shows its empty state in their place */
/* its content 16px in from every edge, the last row's fill too, hovered or picked (owner, 21 Nov: "padding is off") */
.dm-ttx{position:relative;width:100%;padding:16px;container:ttx/inline-size;--dm-ttx-r:calc(10px * var(--dm-rk-m,var(--dm-rk)))}
/* the head: the mark, then the title and its summary, or, while rows are picked, what you can do to them */
.dm-ttx-hd{display:flex;align-items:center;gap:12px;padding-bottom:12px;border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.dm-ttx-hi{width:28px;height:28px;display:grid;place-items:center;flex:none;border-radius:var(--dm-r-sm);color:var(--dm-fg2);background:var(--dm-chip)}
.dm-ttx-hx{position:relative;flex:1;min-width:0;height:28px}
.dm-ttx-ti,.dm-ttx-sb{position:absolute;inset:0;display:flex;align-items:center;transition:opacity .28s var(--dm-ease),transform .45s var(--dm-ease),filter .28s var(--dm-ease)}
/* the title and its count share one baseline; the title's 20px line sits centred in the 28px head (4px above it) */
.dm-ttx-ti{gap:8px;white-space:nowrap;align-items:baseline;padding-top:4px}
.dm-ttx-ti b{flex:none;font-size:14px;font-weight:500;line-height:20px}
.dm-ttx-sum{min-width:0;font-size:12.5px;line-height:18px;overflow:hidden;text-overflow:ellipsis}
.dm-ttx-sb{gap:2px;opacity:0;transform:translateY(10px);filter:blur(3px);pointer-events:none}
.dm-ttx.dm-selecting .dm-ttx-ti{opacity:0;transform:translateY(-10px);filter:blur(3px);pointer-events:none}
.dm-ttx.dm-selecting .dm-ttx-sb{opacity:1;transform:none;filter:none;pointer-events:auto}
.dm-ttx-n{margin-right:8px;font-size:13px;font-weight:500;white-space:nowrap}
.dm-ttx-sp{flex:1}
/* Clear's words end over the times, 8px inside the rows' fill, its hover box reaching out round them */
.dm-ttx-sb .dm-ttx-clr{margin-right:-3px}
.dm-ttx-sb .dm-pill.dm-ttx-del{color:var(--dm-bad)}
@media (hover:hover) and (pointer:fine){.dm-ttx-sb .dm-pill.dm-ttx-del:hover{background:color-mix(in srgb,var(--dm-bad) 10%,transparent);color:var(--dm-bad)}}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov) */
.dm-ttx :is(.dm-pill,.dm-ib):active{transform:none}
/* the table: the checkbox column under the head's mark, the task's name taking the room that is left (cut short with an
   ellipsis rather than pushing the card wider), and the other columns as wide as their words. Rows stand 2px apart, and
   the headings sit right under the divider, as close as any first line (owner, 18 Nov: no padding added on top) */
.dm-ttx-t{width:100%;margin:-2px 0;border-collapse:separate;border-spacing:0 2px;font-size:13px}
.dm-ttx-t th{height:32px;padding:0 8px;text-align:left;font-weight:500;font-size:12px;color:var(--dm-muted);white-space:nowrap}
.dm-ttx-t td{height:36px;padding:0 8px;white-space:nowrap;transition:background-color .25s var(--dm-ease)}
.dm-ttx-t :is(th,td).dm-ck{width:28px;padding:0}
.dm-ttx-t :is(th,td).dm-ck .dm-ttx-cb{margin:0 6px}
.dm-ttx-t :is(th,td).dm-nm{width:100%;max-width:0;padding-left:12px;overflow:hidden;text-overflow:ellipsis}
.dm-ttx-t :is(th,td).dm-r{text-align:right}
/* it reads as a table of columns (owner, 21 Nov: "there are not vertical lines here again, why?"): a hairline after every column
   from Task to the one before the last, in every style and wherever the columns have been moved, the checkbox staying with
   the task's name. Each cell's line reaches 1px over the 2px between rows, so the lines run unbroken. The columns resize and
   move as in a spreadsheet (cols()); sized by hand, a cell too narrow for its words cuts them short */
.dm-ttx{--dm-ttx-col:color-mix(in srgb,color-mix(in srgb,var(--dm-line),var(--dm-fg) 9%) 50%,transparent)}
.dm-ttx-t :is(th,td):not(.dm-ck){position:relative}
.dm-ttx-t :is(th,td):not(:first-child):not(:last-child)::after{content:"";position:absolute;right:0;top:-1px;bottom:-1px;width:1px;background:var(--dm-ttx-col);pointer-events:none}
.dm-ttx-t.dm-cols-rz td:not(.dm-ck){overflow:hidden;text-overflow:ellipsis}
.dm-ttx-t.dm-cols-rz :is(th,td):is(.dm-ck,.dm-nm){width:auto;max-width:none}
/* columns sized wider than the card scroll sideways inside it, as a spreadsheet's do */
.dm-ttx-sc:has(>.dm-ttx-t.dm-cols-rz){overflow-x:auto}
.dm-ttx-t.dm-cols-rz th .dm-ttx-s{max-width:100%}
/* a header sorts its column: a quiet arrow shows on hover and stays on the column the rows are sorted by. Over a column set
   to the right the arrow goes before the word, so the word ends where the column's figures do */
.dm-ttx-s{display:inline-flex;align-items:center;gap:3px;height:24px;margin:0 -6px;padding:0 6px;border-radius:calc(6px * var(--dm-rk-s,var(--dm-rk)));color:inherit;font:inherit;transition:color .2s,background-color .2s}
.dm-ttx-t th.dm-r .dm-ttx-s{flex-direction:row-reverse}
@media (hover:hover) and (pointer:fine){.dm-ttx-s:hover{color:var(--dm-fg);background:var(--dm-row)}}
.dm-ttx-s .dm-ar{display:grid;opacity:0;transition:opacity .2s,transform .35s var(--dm-ease)}
@media (hover:hover) and (pointer:fine){.dm-ttx-s:hover .dm-ar{opacity:.45}}
.dm-ttx-s.dm-on{color:var(--dm-fg)}
.dm-ttx-s.dm-on .dm-ar{opacity:1}
.dm-ttx-s.dm-on.dm-desc .dm-ar{transform:rotate(180deg)}
/* rows: the shared hover, and a slightly deeper grey while picked, with the fill's corners round at its two ends */
.dm-ttx-t tbody tr[data-id]{cursor:pointer}
.dm-ttx-t tbody tr[data-id]>td:first-child{border-radius:var(--dm-ttx-r) 0 0 var(--dm-ttx-r)}
.dm-ttx-t tbody tr[data-id]>td:last-child{border-radius:0 var(--dm-ttx-r) var(--dm-ttx-r) 0}
@media (hover:hover) and (pointer:fine){.dm-ttx-t tbody tr[data-id]:hover>td{background:var(--dm-row)}}
.dm-ttx-t tbody tr.dm-sel>td{background:color-mix(in srgb,var(--dm-fg) 6%,transparent)}
@media (hover:hover) and (pointer:fine){.dm-ttx-t tbody tr.dm-sel:hover>td{background:color-mix(in srgb,var(--dm-fg) 8%,transparent)}}
.dm-ttx-t td.dm-nm{font-weight:500}
.dm-ttx-t .dm-ag{display:flex;align-items:center;gap:7px;min-width:0;color:var(--dm-fg2)}
/* a long agent name is cut short with an ellipsis rather than running into the time beside it */
.dm-ttx-t .dm-ag>span{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.dm-ttx-t .dm-ag .dm-av{width:20px;height:20px;font-size:9.5px}
.dm-ttx-t td.dm-num{color:var(--dm-fg2)}
.dm-ttx-t td.dm-up{color:var(--dm-muted)}
/* on a picked row's grey the times step up a shade, so they keep 4.5:1 */
.dm-ttx-t tbody tr.dm-sel td.dm-up{color:var(--dm-fg2)}
/* checkboxes: a clear 1.5px edge, and a tick that springs in; select-all shows a dash while only some rows are picked */
.dm-ttx-cb{display:grid;place-items:center;width:16px;height:16px;border-radius:var(--dm-r-tiny,5px);box-shadow:inset 0 0 0 1.5px var(--dm-fg2);color:var(--dm-on-accent,#fff);transition:background-color .2s,box-shadow .2s}
@media (hover:hover) and (pointer:fine){.dm-ttx-cb:hover{box-shadow:inset 0 0 0 1.5px var(--dm-fg)}}
.dm-ttx-cb[aria-checked="true"],.dm-ttx-cb[aria-checked="mixed"]{background:var(--dm-accent);box-shadow:inset 0 0 0 1px var(--dm-accent-mark,var(--dm-accent))}
.dm-ttx-cb svg{grid-area:1/1;width:11px;height:11px;opacity:0;transform:scale(.4);transition:opacity .15s,transform .3s cubic-bezier(.34,1.4,.64,1)}
.dm-ttx-cb[aria-checked="true"] .dm-ck-y,.dm-ttx-cb[aria-checked="mixed"] .dm-ck-m{opacity:1;transform:none}
/* status: the tag's look, its status tint with its words in that hue: Running in the accent, Done green, Failed red, Queued
   and Paused grey. The tint is mixed into the surface, so the chip is opaque and its words keep 4.5:1 and APCA Lc 60 on a
   picked row and in dark mode too */
.dm-ttx-st{--dm-sc:var(--dm-fg2);--dm-sb:var(--dm-chip);display:inline-flex;align-items:center;height:22px;padding:0 9px 0 7px;border-radius:var(--dm-r-tag);font-size:12px;font-weight:500;color:var(--dm-sc);background:color-mix(in srgb,var(--dm-sb) 70%,var(--dm-surface));transition:color .35s var(--dm-ease),background-color .35s var(--dm-ease)}
@supports (corner-shape:squircle){.dm-ttx-st{border-radius:var(--dm-r-tag-sq)}}
.dm-ttx-st .dm-sv{display:inline-flex;align-items:center;gap:6px}
/* running reads in the accent's text colour on a tint of its mark, so a light accent like lime stays legible */
.dm-ttx-st[data-s="run"]{--dm-sc:var(--dm-accent-fg,var(--dm-accent));--dm-sb:var(--dm-accent-bg)}
.dm-ttx-st[data-s="done"]{--dm-sc:var(--dm-ok);--dm-sb:var(--dm-ok-bg)}
.dm-ttx-st[data-s="fail"]{--dm-sc:var(--dm-bad);--dm-sb:var(--dm-bad-bg)}
.dm-ttx-st .dm-spin{width:10px;height:10px}
.dm-ttx-st .dm-i{width:12px;height:12px}
/* a new status fades in out of a blur; a cancelled row slides away before it goes */
.dm-ttx-sin{animation:dm-ttxsin .32s var(--dm-ease)}
@keyframes dm-ttxsin{from{opacity:0;filter:blur(3px)}}
.dm-ttx-t tbody tr.dm-ttx-out{opacity:0;transform:translateX(14px);transition:opacity .24s var(--dm-ease),transform .24s var(--dm-ease)}
/* when every task is gone: a small sketch of the table on a card, what happened, and a way to bring them back. Soft's
   sketch is a soft card with three rows, the first one's box in the accent's tint; Blueprint keeps its mark */
.dm-ttx-t tbody tr.dm-ttx-empty td{height:auto;max-width:none;padding:24px 16px 26px;text-align:center;white-space:normal}
.dm-ttx.dm-none .dm-ttx-t thead{display:none}
.dm-ttx-sum:empty{display:none}
.dm-ttx-em{display:flex;flex-direction:column;align-items:center;gap:4px}
